from collections import Counter, deque


def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    background = Counter(v for row in g for v in row).most_common(1)[0][0]
    seen = set()
    for r in range(h):
        for c in range(w):
            if (r, c) in seen or g[r][c] == background:
                continue
            color = g[r][c]
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and g[yy][xx] == color:
                        seen.add((yy,xx))
                        q.append((yy,xx))
            r0, r1 = min(y for y,x in comp), max(y for y,x in comp)
            c0, c1 = min(x for y,x in comp), max(x for y,x in comp)
            if r1-r0 < 2 or c1-c0 < 2:
                continue
            perimeter = set()
            perimeter.update((r0,x) for x in range(c0,c1+1))
            perimeter.update((r1,x) for x in range(c0,c1+1))
            perimeter.update((y,c0) for y in range(r0,r1+1))
            perimeter.update((y,c1) for y in range(r0,r1+1))
            if set(comp) != perimeter:
                continue
            # Odd-sided hollow frames fill with 7; even-sided frames with 2.
            fill = 7 if (r1-r0+1) % 2 else 2
            for y in range(r0+1,r1):
                for x in range(c0+1,c1):
                    if g[y][x] == background:
                        g[y][x] = fill
    return g
